using System;
using System.Collections.Generic;
using System.Globalization;

namespace ClearView.Core
{
    public enum LabelCategory
    {
        /// <summary>Detected but neither hidden nor protected.</summary>
        Ignore = 0,
        /// <summary>Advertising: candidate to be hidden.</summary>
        Ad = 1,
        /// <summary>Safety-critical: must never be covered (people, vehicles, traffic signals...).</summary>
        Safety = 2,
    }

    /// <summary>
    /// Maps model class indices to names and categories.
    /// Text format (one class per line, generated by ml/scripts/export.py):
    /// <code>index,name,category</code> where category is ad | safety | ignore.
    /// Blank lines and lines starting with '#' are skipped.
    /// </summary>
    public sealed class LabelMap
    {
        private readonly string[] _names;
        private readonly LabelCategory[] _categories;

        public LabelMap(string[] names, LabelCategory[] categories)
        {
            if (names == null) throw new ArgumentNullException(nameof(names));
            if (categories == null) throw new ArgumentNullException(nameof(categories));
            if (names.Length != categories.Length)
                throw new ArgumentException("names and categories must have the same length");
            _names = names;
            _categories = categories;
        }

        public int Count => _names.Length;
        public string Name(int classId) => _names[classId];
        public LabelCategory Category(int classId) => _categories[classId];

        public static LabelMap Parse(string text)
        {
            if (text == null) throw new ArgumentNullException(nameof(text));
            var entries = new SortedDictionary<int, KeyValuePair<string, LabelCategory>>();
            string[] lines = text.Replace("\r", "").Split('\n');
            for (int lineNo = 0; lineNo < lines.Length; lineNo++)
            {
                string line = lines[lineNo].Trim();
                if (line.Length == 0 || line[0] == '#') continue;
                string[] parts = line.Split(',');
                if (parts.Length != 3)
                    throw new FormatException($"Line {lineNo + 1}: expected 'index,name,category' but got '{line}'");
                if (!int.TryParse(parts[0].Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int index) || index < 0)
                    throw new FormatException($"Line {lineNo + 1}: invalid class index '{parts[0]}'");
                if (entries.ContainsKey(index))
                    throw new FormatException($"Line {lineNo + 1}: duplicate class index {index}");
                entries[index] = new KeyValuePair<string, LabelCategory>(parts[1].Trim(), ParseCategory(parts[2].Trim(), lineNo + 1));
            }

            if (entries.Count == 0) throw new FormatException("Label file contains no classes");
            var names = new string[entries.Count];
            var cats = new LabelCategory[entries.Count];
            int expected = 0;
            foreach (var kv in entries)
            {
                if (kv.Key != expected)
                    throw new FormatException($"Class indices must be contiguous from 0; missing index {expected}");
                names[expected] = kv.Value.Key;
                cats[expected] = kv.Value.Value;
                expected++;
            }
            return new LabelMap(names, cats);
        }

        private static LabelCategory ParseCategory(string s, int lineNo)
        {
            switch (s.ToLowerInvariant())
            {
                case "ad": return LabelCategory.Ad;
                case "safety": return LabelCategory.Safety;
                case "ignore": return LabelCategory.Ignore;
                default: throw new FormatException($"Line {lineNo}: unknown category '{s}' (use ad, safety or ignore)");
            }
        }
    }
}
